<?php
declare(strict_types=1);
require dirname(__DIR__,2).'/bootstrap.php';
use App\Core\Auth;use App\Core\Csrf;use App\Core\Database;use App\Services\DanceCupScoringService;
Auth::requireAdmin();$pdo=Database::connection();$test=(string)($_GET['data_mode']??$_POST['data_mode']??'')==='test';if($test&&!Auth::isSuperAdmin()){http_response_code(403);exit('Super Admin access required.');}$t=DanceCupScoringService::tables($test);$error='';$notice=isset($_GET['event_created'])?'Dance Cup event created.':(isset($_GET['created'])?'Dance Cup category created.':'');
try{if($_SERVER['REQUEST_METHOD']==='POST'){if(!Csrf::verify($_POST['_csrf']??null))throw new RuntimeException('Invalid security token.');$action=(string)($_POST['action']??'create_category');if($action==='create_event'){$name=trim((string)($_POST['event_name']??''));if($name==='')throw new RuntimeException('Event name is required.');$q=$pdo->prepare("INSERT INTO {$t['events']}(name,event_date,end_date,venue,country,status,created_by) VALUES(:n,:d,:end,:v,:c,'draft',:u)");$q->execute(['n'=>$name,'d'=>$_POST['event_date']?:null,'end'=>$_POST['end_date']?:null,'v'=>trim((string)($_POST['venue']??''))?:null,'c'=>trim((string)($_POST['country']??''))?:null,'u'=>(int)(Auth::user()['id']??0)?:null]);header('Location: ?event_created=1'.($test?'&data_mode=test':''),true,303);exit;}$criteria=[];$names=(array)($_POST['criterion_name']??[]);$max=(array)($_POST['criterion_max']??[]);foreach($names as $i=>$name)if(trim((string)$name)!==''||trim((string)($max[$i]??''))!=='')$criteria[]=['name'=>trim((string)$name),'max'=>(float)($max[$i]??0)];DanceCupScoringService::createCompetition($pdo,$_POST,$criteria,(int)(Auth::user()['id']??0),$test);header('Location: ?created=1'.($test?'&data_mode=test':''),true,303);exit;}}catch(Throwable $e){$error=$e->getMessage();}
$events=$pdo->query("SELECT * FROM {$t['events']} WHERE status<>'archived' ORDER BY event_date DESC,id DESC")->fetchAll();$competitions=$pdo->query("SELECT c.*,e.name event_name,e.event_date,(SELECT COUNT(*) FROM {$t['criteria']} x WHERE x.competition_id=c.id) criterion_count FROM {$t['competitions']} c JOIN {$t['events']} e ON e.id=c.event_id ORDER BY c.updated_at DESC,c.id DESC")->fetchAll();$csrf=Csrf::token();$suffix=$test?'&data_mode=test':'';
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Dance Cup Scoring</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link href="../../public/css/scoring-premium.css?v=317" rel="stylesheet"><style>.criterion-row{display:grid;grid-template-columns:minmax(0,1fr) 150px 44px;gap:.6rem;margin-bottom:.6rem}.dc-row{cursor:pointer}.dc-row:hover{background:#f3f7ff}@media(max-width:575px){.criterion-row{grid-template-columns:minmax(0,1fr) 105px 42px}}</style></head><body class="bg-light"><nav class="navbar navbar-dark bg-dark"><div class="container-fluid"><a class="navbar-brand" href="../">BDC Scoring</a><a class="btn btn-outline-light btn-sm" href="../">Dashboard</a></div></nav><main class="container-fluid py-4" style="max-width:1500px"><span class="badge <?=$test?'text-bg-danger':'text-bg-warning'?>"><?=$test?'TEST ONLY · ':''?>DANCE CUP</span><h1 class="h3 mt-2">Dance Cup Scoring Dashboard</h1><p class="text-muted">Independent Dance Cup events and categories. No Jack &amp; Jill events or points.</p><?php if($notice):?><div class="alert alert-success"><?=e($notice)?></div><?php endif;?><?php if($error):?><div class="alert alert-danger"><?=e($error)?></div><?php endif;?>
<section class="card border-0 shadow-sm mb-4"><div class="card-body p-4"><h2 class="h5">1. Create Dance Cup Event</h2><form method="post"><input type="hidden" name="_csrf" value="<?=e($csrf)?>"><input type="hidden" name="action" value="create_event"><input type="hidden" name="data_mode" value="<?=$test?'test':'real'?>"><div class="row g-3"><div class="col-lg-4"><label class="form-label">Event Name</label><input class="form-control" name="event_name" required placeholder="e.g. 1st Asia Open Dance Cup"></div><div class="col-md-2"><label class="form-label">Start Date</label><input class="form-control" type="date" name="event_date"></div><div class="col-md-2"><label class="form-label">End Date</label><input class="form-control" type="date" name="end_date"></div><div class="col-md-2"><label class="form-label">Venue</label><input class="form-control" name="venue"></div><div class="col-md-2"><label class="form-label">Country</label><input class="form-control" name="country"></div><div class="col-12"><button class="btn btn-dark">Create Event Draft</button></div></div></form></div></section>
<section class="card border-0 shadow-sm mb-4"><div class="card-body p-4"><h2 class="h5">2. Create Category</h2><?php if(!$events):?><div class="alert alert-warning">Create a Dance Cup event above first.</div><?php else:?><form method="post"><input type="hidden" name="_csrf" value="<?=e($csrf)?>"><input type="hidden" name="action" value="create_category"><input type="hidden" name="data_mode" value="<?=$test?'test':'real'?>"><div class="row g-3"><div class="col-lg-6"><label class="form-label">Dance Cup Event</label><select class="form-select" name="event_id" required><option value="">Select Dance Cup event</option><?php foreach($events as $event):?><option value="<?=(int)$event['id']?>"><?=e(($event['event_date']?:'Date pending').' — '.$event['name'])?></option><?php endforeach;?></select></div><div class="col-lg-6"><label class="form-label">Category Name</label><input class="form-control" name="category_name" required placeholder="e.g. Bachata Solo Open"></div><div class="col-md-3"><label class="form-label">Dance Style</label><select class="form-select" name="dance_style"><option value="salsa">Salsa</option><option value="bachata" selected>Bachata</option><option value="cha_cha">Cha Cha</option><option value="other">Other / Custom</option></select></div><div class="col-md-3"><label class="form-label">Entry Type</label><select class="form-select" name="entry_type"><option value="solo">Solo</option><option value="couple">Couple</option><option value="duo">Duo</option><option value="team">Team</option></select></div><div class="col-md-3"><label class="form-label">Level</label><select class="form-select" name="competition_level"><option value="open" selected>Open</option><option value="professional">Professional</option><option value="pro_am">Pro-Am</option><option value="intermediate">Intermediate</option><option value="amateur">Amateur</option></select></div><div class="col-md-3"><label class="form-label">Performance Type</label><select class="form-select" name="performance_type"><option value="showcase">Showcase</option><option value="classic">Classic</option><option value="cabaret">Cabaret</option><option value="shines">Shines</option><option value="just_dance">Just Dance</option></select></div><div class="col-md-3"><label class="form-label">Round</label><select class="form-select" name="round_name"><option value="qualifier">Qualifier</option><option value="quarterfinal">Quarterfinal</option><option value="semifinal">Semifinal</option><option value="final" selected>Final</option></select></div><div class="col-12"><div class="d-flex justify-content-between"><label class="fw-bold">Scoring Criteria</label><span class="badge text-bg-dark">Total: <span id="criteriaTotal">100</span></span></div><div id="criteriaRows" class="mt-2"></div><button class="btn btn-sm btn-outline-primary" type="button" id="addCriterion">+ Add Criterion</button></div><div class="col-12"><button class="btn btn-warning btn-lg">Create Category Draft</button></div></div></form><?php endif;?></div></section>
<section class="card border-0 shadow-sm"><div class="card-body"><h2 class="h5">Dance Cup Categories</h2><div class="table-responsive"><table class="table align-middle"><thead><tr><th>Event</th><th>Category</th><th>Style</th><th>Level</th><th>Entry</th><th>Round</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($competitions as $c):?><tr class="dc-row" onclick="location.href='category.php?id=<?=(int)$c['id']?><?=$suffix?>'"><td><strong><?=e($c['event_name'])?></strong></td><td><?=e($c['category_name'])?></td><td><?=e(ucwords(str_replace('_',' ',$c['dance_style'])))?></td><td><strong><?=e(ucwords(str_replace('_',' ',$c['competition_level'])))?></strong></td><td><?=e(ucfirst($c['entry_type']))?></td><td><?=e(ucfirst($c['round_name']))?></td><td><span class="badge text-bg-secondary"><?=e(ucfirst($c['status']))?></span></td><td><a class="btn btn-sm btn-primary" href="category.php?id=<?=(int)$c['id']?><?=$suffix?>">Open Draft</a></td></tr><?php endforeach;?><?php if(!$competitions):?><tr><td colspan="8" class="text-center text-muted py-5">No Dance Cup categories yet.</td></tr><?php endif;?></tbody></table></div></div></section></main>
<script>const defaults=[['Timing',20],['Musicality / Choreography',20],['Technique',20],['Difficulty',15],['Connection / Synchronisation',15],['Presentation',10]],rows=document.getElementById('criteriaRows'),total=document.getElementById('criteriaTotal');function recalc(){if(total)total.textContent=[...document.querySelectorAll('.criterion-max')].reduce((s,x)=>s+(Number(x.value)||0),0).toFixed(2).replace(/\.00$/,'')}function add(name='',max=''){const row=document.createElement('div');row.className='criterion-row';row.innerHTML='<input class="form-control" name="criterion_name[]" required><input class="form-control criterion-max" type="number" name="criterion_max[]" min="0.01" max="1000" step="0.01" required><button class="btn btn-outline-danger" type="button">×</button>';row.children[0].value=name;row.children[1].value=max;row.children[1].oninput=recalc;row.children[2].onclick=()=>{row.remove();recalc()};rows.appendChild(row);recalc()}if(rows){defaults.forEach(x=>add(...x));document.getElementById('addCriterion').onclick=()=>add()}</script></body></html>
